import { loadRemoteModule as loadRemoteModuleFromFederation } from '@angular-architects/module-federation';
import { runtimeEnv } from './runtime-config';

/**
 * Loads a module exposed by the remote micro frontend.
 *
 * The remote entry URL is read at runtime from `window.__env` (populated by
 * `env-config.js`, generated by `docker-entrypoint.sh`), falling back to the
 * value declared in the environment files. This keeps the "build once, deploy
 * everywhere" contract: no rebuild is needed when the remote URL changes.
 */
export function loadRemoteModule<T = unknown>(exposedModule: string): Promise<T> {
  return loadRemoteModuleFromFederation<T>({
    type: 'module',
    remoteEntry: runtimeEnv.remoteAppUrl,
    exposedModule,
  });
}
